def render_header():
    st.markdown('''<div class="brand-row"><div class="brand-mark">↻</div><div class="brand-name">wastewise</div><div class="brand-note">A calmer way to sort</div></div>
    <div class="hero"><div class="hero-kicker">SMALL CHOICES, BETTER HABITS</div><h1>Where should this go?</h1><p>Get a clear sorting suggestion and practical next steps for everyday waste. Start with a photo, add a description, and we’ll help you think it through.</p><div class="hero-pill">✦ &nbsp; Image + description assistance</div></div>''', unsafe_allow_html=True)

def render_result(category: str, item: str, confidence, source: str):
    info = CATEGORY_INFO[category]
    item = escape(item)
    trust = (f"Model estimate · {confidence:.0%}" if confidence is not None and confidence >= 0.62 else "Low confidence · please confirm") if confidence is not None else ("Description-based suggestion" if source == "text" else "Your selected category")
    st.markdown(f'''<div class="result-card"><div class="result-icon {info['color']}">{info['icon']}</div><div><div class="result-label">IDENTIFIED ITEM</div><h3>{item}</h3><p>Sorting group: {info['label']}</p></div><div class="confidence"><strong>{trust}</strong><span>Suggestions can be wrong</span></div></div>''', unsafe_allow_html=True)

def render_category_card(category: str, item: str = ""):
    info = CATEGORY_INFO[category]
    clean_item = item.lower()
    specific_steps = next((steps for key, steps in ITEM_STEPS.items() if key in clean_item), None)
    selected_steps = specific_steps or info["steps"]
    steps = "".join(f"<li>{escape(step)}</li>" for step in selected_steps)
    links = "".join(f'<a href="{url}" target="_blank" rel="noopener">{label} ↗</a>' for label, url in info["links"])
    st.markdown(f'''<div class="guide-card"><div class="guide-head"><div class="mini-icon {info['color']}">{info['icon']}</div><div><h3>{info['label']}</h3><div class="guide-sub">{info['short']}</div></div></div><ol>{steps}</ol><div class="guide-note">{info['note']}</div><div class="resource-links">{links}</div></div>''', unsafe_allow_html=True)
